// Generate a valid hop_size in [1, 1024] to bound allocations for subsequent processing
size_t hop_size = (size_t)(*FUZZ_PARAM(unsigned int) % 1024) + 1;
// Generate a valid threshold in [0.0, 1.0] with millisecond precision for attribute tracking
unsigned int thr_milli = *FUZZ_PARAM(unsigned int) % 1001; // 0..1000
float threshold = (float)thr_milli / 1000.0f;

// Allocate persistent storage for the opaque handle value; this storage itself is kept in the pool
// The API will write the implementation-defined pointer value into *handle
ten_vad_handle_t *handle = (ten_vad_handle_t *)malloc(sizeof(ten_vad_handle_t));
if (!handle) { FUZZ_BAIL(); }
*handle = (ten_vad_handle_t)0; // initialize to NULL prior to creation

// Invoke create. Requirements enforced: non-null handle storage, positive hop_size, threshold in [0,1]
int rc = ten_vad_create(handle, hop_size, threshold);
if (rc != 0) { FUZZ_BAIL(); }

// Track configuration/state on the handle storage for later validation and correct API usage
FUZZ_SET_ATTR_INT(handle, "created", 1);
FUZZ_SET_ATTR_INT(handle, "hop_size", (int)hop_size);
FUZZ_SET_ATTR_INT(handle, "thresh_milli", (int)thr_milli);

// Output: the storage pointer, which now holds a valid opaque instance pointer

// Validate input storage pointer and that it represents an active, created instance
if (!handle) { FUZZ_BAIL(); }
int created = FUZZ_GET_ATTR_INT(handle, "created");
if (created != 1) { FUZZ_BAIL(); }
// The API expects a valid opaque handle value (not the storage pointer)
ten_vad_handle_t hval = *handle;
if (!hval) { FUZZ_BAIL(); }

// Retrieve the hop_size configured at creation; enforce bounds to keep allocations small
int hop_size = FUZZ_GET_ATTR_INT(handle, "hop_size");
if (hop_size <= 0 || hop_size > 1024) { FUZZ_BAIL(); }

// Build exactly one analysis frame of int16_t PCM samples of length hop_size
// Use FUZZ_PARAM_STR() as a source of bytes and map into int16_t values
std::string src = FUZZ_PARAM_STR();
if (src.size() == 0) { FUZZ_BAIL(); }
int16_t *frame = (int16_t *)malloc((size_t)hop_size * sizeof(int16_t));
if (!frame) { FUZZ_BAIL(); }
// Fill deterministically from src bytes to avoid undefined reads
const unsigned char *bytes = (const unsigned char *)src.data();
size_t blen = src.size();
for (int i = 0; i < hop_size; ++i) {
    unsigned char b0 = bytes[(2u * (unsigned)i) % blen];
    unsigned char b1 = bytes[(2u * (unsigned)i + 1u) % blen];
    // Little-endian assemble into signed 16-bit
    int16_t sample = (int16_t)((uint16_t)b0 | ((uint16_t)b1 << 8));
    frame[i] = sample;
}

float out_probability = -1.0f;
int out_flag = -1;
int rc = ten_vad_process(hval, frame, (size_t)hop_size, &out_probability, &out_flag);
free(frame);
if (rc != 0) { FUZZ_BAIL(); }

// Postconditions required by API
FUZZ_ASSERT(out_probability >= 0.0f && out_probability <= 1.0f, "probability out of [0,1]");
FUZZ_ASSERT(out_flag == 0 || out_flag == 1, "flag not binary");

// Decision property: flag must reflect probability vs threshold configured at creation
int thr_milli = FUZZ_GET_ATTR_INT(handle, "thresh_milli");
float threshold = (float)thr_milli / 1000.0f;
int expected_flag = (out_probability >= threshold) ? 1 : 0;
FUZZ_ASSERT(out_flag == expected_flag, "flag does not match threshold comparison");

// Output: the handle storage remains valid and is returned to the pool

// Validate input storage pointer and that it represents an active, created instance
if (!handle) { FUZZ_BAIL(); }
int created = FUZZ_GET_ATTR_INT(handle, "created");
if (created != 1) { FUZZ_BAIL(); }
if (!*handle) { FUZZ_BAIL(); }

// Invoke destroy; on success, *handle must be set to NULL by the API
int rc = ten_vad_destroy(handle);
if (rc != 0) { FUZZ_BAIL(); }
FUZZ_ASSERT(*handle == (ten_vad_handle_t)0, "*handle not NULL after destroy");

// Update state to reflect the destroyed instance; storage remains reusable
FUZZ_SET_ATTR_INT(handle, "created", 0);
// Keep hop_size/thresh_milli attributes for potential reuse by another create if desired

// Simple query function with no inputs/outputs; verify returned pointer is non-null and looks like a C-string
const char *ver = ten_vad_get_version();
if (!ver) { FUZZ_BAIL(); }
// Validate it is reasonably small and null-terminated within a bound to avoid unbounded scans
size_t max_scan = 256;
size_t i = 0;
for (; i < max_scan && ver[i] != '\0'; ++i) {}
FUZZ_ASSERT(i < max_scan, "version string not null-terminated within bound");

