import random
import struct
from typing import List, Tuple

# This generator produces a bytes buffer intended for FUZZ_PARAM_STR in the stub.
# The stub maps consecutive little-endian 16-bit words from this byte string into
# a hop_size-length int16 frame via modulo indexing. Therefore, producing a mix of
# patterns in the underlying bytes will yield frames that can represent silence,
# tones, speech-like envelopes, clipped peaks, and noise-like content.
#
# Constraints inferred from the fuzzer stub and API:
# - hop_size is in (0, 1024]; process requires exactly one frame of that length.
# - FUZZ_PARAM_STR must be non-empty; bytes are consumed in pairs (with wrap).
# - Little-endian int16 assembly is used.
#
# Strategy:
# - Build a composite byte buffer made of several segments. Each segment is an
#   array of int16 samples serialized little-endian. We include patterns:
#   * Silence (0)
#   * Low-amplitude noise
#   * High-amplitude (near-clipping) noise
#   * Single-frequency sine waves at various amplitudes
#   * Square and sawtooth waves
#   * Impulses and DC offsets
#   * Gradual ramps (fade in/out)
# - Keep total size <= 4096 bytes.
# - Randomize order and parameters seeded by the input seed.
#
# Even though the exact hop_size is unknown at generation time, the modulo access
# in the stub ensures any non-empty buffer works. Providing diverse content
# increases the chance that constructed frames vary across calls and trigger
# different probability/threshold branches.

MAX_BYTES = 4096


def _pack_int16(vals: List[int]) -> bytes:
    # Clamp and pack to little-endian int16
    out = bytearray()
    for v in vals:
        if v > 32767:
            v = 32767
        elif v < -32768:
            v = -32768
        out += struct.pack('<h', v)
    return bytes(out)


def _gen_silence(n: int) -> bytes:
    return _pack_int16([0] * n)


def _gen_noise(n: int, amp: int, rng: random.Random) -> bytes:
    # Uniform noise in [-amp, amp]
    vals = [rng.randint(-amp, amp) for _ in range(n)]
    return _pack_int16(vals)


def _gen_sine(n: int, amp: int, period_samples: float, phase: float) -> bytes:
    import math
    vals = []
    for i in range(n):
        s = math.sin((2.0 * math.pi * i) / period_samples + phase)
        vals.append(int(amp * s))
    return _pack_int16(vals)


def _gen_square(n: int, amp: int, period_samples: int, duty: float) -> bytes:
    duty = max(0.01, min(0.99, duty))
    vals = []
    for i in range(n):
        t = i % period_samples
        on = t < int(period_samples * duty)
        vals.append(amp if on else -amp)
    return _pack_int16(vals)


def _gen_saw(n: int, amp: int, period_samples: int) -> bytes:
    vals = []
    for i in range(n):
        t = i % period_samples
        # Map t in [0, period) to [-amp, amp]
        v = int((-amp) + (2.0 * amp) * (t / max(1, period_samples - 1)))
        vals.append(v)
    return _pack_int16(vals)


def _gen_impulses(n: int, amp: int, every: int) -> bytes:
    vals = []
    for i in range(n):
        if every > 0 and (i % every) == 0:
            vals.append(amp if ((i // max(1, every)) % 2) == 0 else -amp)
        else:
            vals.append(0)
    return _pack_int16(vals)


def _gen_dc(n: int, level: int) -> bytes:
    return _pack_int16([level] * n)


def _gen_ramp(n: int, start: int, end: int) -> bytes:
    if n <= 1:
        return _pack_int16([start])
    vals = []
    for i in range(n):
        t = i / (n - 1)
        v = int(round(start + (end - start) * t))
        vals.append(v)
    return _pack_int16(vals)


def _choose_period(rng: random.Random) -> int:
    # Choose musically interesting or arbitrary small integer periods to vary spectral content
    candidates = [16, 20, 21, 24, 32, 40, 48, 50, 64, 80, 96, 100, 128, 160, 192, 200, 256]
    return rng.choice(candidates)


def _choose_amp(rng: random.Random, level: str) -> int:
    if level == 'low':
        return rng.randint(300, 2000)
    if level == 'mid':
        return rng.randint(2000, 12000)
    # high
    return rng.randint(18000, 32000)


def _shuffle_segments(segs: List[bytes], rng: random.Random) -> List[bytes]:
    rng.shuffle(segs)
    return segs


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Determine a target total sample count. We want enough bytes so modulo access
    # produces variety across hop_size up to 1024. Pick between 128 and 1536 samples.
    total_samples_target = rng.randint(128, 1536)

    segments: List[bytes] = []

    # Always include a brief silence and a ramp to anchor extremes.
    segments.append(_gen_silence(rng.randint(16, 96)))
    segments.append(_gen_ramp(rng.randint(32, 192), -2000, 2000))

    # Add a few randomized waveform segments
    count_wave_segs = rng.randint(4, 9)
    for _ in range(count_wave_segs):
        kind = rng.choice([
            'noise_low', 'noise_high', 'sine_low', 'sine_mid', 'sine_high',
            'square', 'saw', 'impulses', 'dc', 'ramp']
        )
        n = rng.randint(24, 256)
        if kind == 'noise_low':
            segments.append(_gen_noise(n, _choose_amp(rng, 'low'), rng))
        elif kind == 'noise_high':
            segments.append(_gen_noise(n, _choose_amp(rng, 'high'), rng))
        elif kind.startswith('sine_'):
            level = kind.split('_')[1]
            amp = _choose_amp(rng, level if level in ('low', 'mid', 'high') else 'mid')
            period = _choose_period(rng)
            phase = rng.uniform(0.0, 2.0 * 3.141592653589793)
            segments.append(_gen_sine(n, amp, float(period), phase))
        elif kind == 'square':
            amp = _choose_amp(rng, rng.choice(['mid', 'high']))
            period = _choose_period(rng)
            duty = rng.uniform(0.2, 0.8)
            segments.append(_gen_square(n, amp, period, duty))
        elif kind == 'saw':
            amp = _choose_amp(rng, rng.choice(['low', 'mid']))
            period = _choose_period(rng)
            segments.append(_gen_saw(n, amp, period))
        elif kind == 'impulses':
            amp = _choose_amp(rng, rng.choice(['mid', 'high']))
            every = rng.choice([4, 8, 12, 16, 24, 32])
            segments.append(_gen_impulses(n, amp, every))
        elif kind == 'dc':
            level = rng.choice([-16000, -8000, -1000, 0, 1000, 8000, 16000, 28000])
            segments.append(_gen_dc(n, level))
        elif kind == 'ramp':
            start = rng.randint(-30000, 30000)
            end = rng.randint(-30000, 30000)
            segments.append(_gen_ramp(n, start, end))

    # Shuffle segments to vary ordering
    _shuffle_segments(segments, rng)

    # Concatenate until reaching the target sample count or byte budget
    out = bytearray()
    for seg in segments:
        if len(out) + len(seg) > MAX_BYTES:
            break
        out.extend(seg)
        if len(out) >= total_samples_target * 2:
            break

    # Ensure non-empty length; if empty (unlikely), fall back to short sine and silence
    if not out:
        out.extend(_gen_silence(32))
        out.extend(_gen_sine(64, 8000, 32.0, 0.0))

    # Trim to MAX_BYTES for safety and to a multiple of 2 bytes to align int16 pairs
    if len(out) % 2 == 1:
        out = out[:-1]
    if len(out) == 0:
        # Guarantee at least one int16 pair
        out.extend(_pack_int16([0, 0]))
    return bytes(out[:MAX_BYTES])
